<?php require __DIR__.'/oyunchu_config.php'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ga_verify();$a=$_POST['action']??'';if($a==='save'){ $id=(int)($_POST['id']??0);$slug=preg_replace('/[^a-z0-9_-]/','',strtolower(trim($_POST['slug']??'')));$name=trim($_POST['default_name']??'');$path=trim($_POST['path']??'');$nk=trim($_POST['name_key']??'');$lk=trim($_POST['logo_key']??'');$dl=trim($_POST['default_logo']??'🎮');$color=trim($_POST['color']??'#999999');$st=trim($_POST['score_table']??'');$sc=trim($_POST['score_col']??'score');$sort=(int)($_POST['sort_order']??0);$active=!empty($_POST['is_active'])?1:0;if($slug===''||$name===''||$path===''||$nk===''||$lk===''){$msg='Bütün məcburi sahələri doldurun.';}else{try{
 $es=$conn->query("CREATE TABLE IF NOT EXISTS es_settings(skey VARCHAR(100) PRIMARY KEY,svalue TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $set=$conn->prepare("INSERT INTO es_settings(skey,svalue) VALUES(?,?) ON DUPLICATE KEY UPDATE svalue=VALUES(svalue)"); $set->bind_param('ss',$nk,$name); $set->execute(); $set->bind_param('ss',$lk,$dl); $set->execute();if($id){$q=$conn->prepare("UPDATE oh_games SET slug=?,path=?,name_key=?,logo_key=?,default_name=?,default_logo=?,color=?,score_table=?,score_col=?,sort_order=?,is_active=? WHERE id=?");$q->bind_param('sssssssssiii',$slug,$path,$nk,$lk,$name,$dl,$color,$st,$sc,$sort,$active,$id);}else{$q=$conn->prepare("INSERT INTO oh_games(slug,path,name_key,logo_key,default_name,default_logo,color,score_table,score_col,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$q->bind_param('sssssssssii',$slug,$path,$nk,$lk,$name,$dl,$color,$st,$sc,$sort,$active);} $q->execute();ga_audit('oyunchu_game_save','oh_games',$id?:$conn->insert_id,$slug);$msg='Yadda saxlanıldı.';}catch(Throwable $e){$msg='Xəta: '.$e->getMessage();}}}elseif($a==='delete'){ $id=(int)$_POST['id'];$q=$conn->prepare('DELETE FROM oh_games WHERE id=?');$q->bind_param('i',$id);$q->execute();ga_audit('oyunchu_game_delete','oh_games',$id);$msg='Oyun silindi.';}}
$edit=null;if(isset($_GET['edit'])){$q=$conn->prepare('SELECT * FROM oh_games WHERE id=?');$id=(int)$_GET['edit'];$q->bind_param('i',$id);$q->execute();$edit=$q->get_result()->fetch_assoc();}$rows=$conn->query('SELECT * FROM oh_games ORDER BY sort_order,id')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Oyunlar</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php'; ?><main class="ga-main"><div class="ga-top"><b>🎮 Oyunlar</b></div><div class="ga-content"><?php if($msg):?><div class="ga-alert"><?=ga_h($msg)?></div><?php endif;?><div class="ga-card"><h3><?= $edit?'Oyunu redaktə et':'Yeni oyun' ?></h3><form method="post" class="ga-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=ga_h($edit['id']??0)?>"><div><label class="ga-label">Slug *</label><input class="ga-input" name="slug" value="<?=ga_h($edit['slug']??'')?>" required></div><div><label class="ga-label">Ad *</label><input class="ga-input" name="default_name" value="<?=ga_h($edit['default_name']??'')?>" required></div><div><label class="ga-label">Path *</label><input class="ga-input" name="path" value="<?=ga_h($edit['path']??'/games/')?>" required></div><div><label class="ga-label">Name key *</label><input class="ga-input" name="name_key" value="<?=ga_h($edit['name_key']??'')?>" required></div><div><label class="ga-label">Logo key *</label><input class="ga-input" name="logo_key" value="<?=ga_h($edit['logo_key']??'')?>" required></div><div><label class="ga-label">Default logo</label><input class="ga-input" name="default_logo" value="<?=ga_h($edit['default_logo']??'🎮')?>"></div><div><label class="ga-label">Rəng</label><input class="ga-input" name="color" value="<?=ga_h($edit['color']??'#999999')?>"></div><div><label class="ga-label">Score cədvəli</label><input class="ga-input" name="score_table" value="<?=ga_h($edit['score_table']??'')?>"></div><div><label class="ga-label">Score sütunu</label><input class="ga-input" name="score_col" value="<?=ga_h($edit['score_col']??'score')?>"></div><div><label class="ga-label">Sıra</label><input class="ga-input" type="number" name="sort_order" value="<?=ga_h($edit['sort_order']??0)?>"></div><div style="padding-top:24px"><label><input type="checkbox" name="is_active" <?=!isset($edit)||$edit['is_active']?'checked':''?>> Aktiv</label></div><div class="full"><button class="ga-btn ga-primary">Yadda saxla</button> <?php if($edit):?><a class="ga-btn ga-mutedbtn" href="oyunchu_games.php">Yeni</a><?php endif;?></div></form></div><br><div class="ga-card"><table class="ga-table"><tr><th>Oyun</th><th>Slug</th><th>Path</th><th>Score</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=ga_h($r['default_logo'].' '.$r['default_name'])?></td><td><?=ga_h($r['slug'])?></td><td><?=ga_h($r['path'])?></td><td><?=ga_h(($r['score_table']??'').' / '.($r['score_col']??''))?></td><td><?=((int)$r['is_active'])?'🟢 Aktiv':'🔴 Passiv'?></td><td><a class="ga-btn ga-mutedbtn" href="?edit=<?=$r['id']?>">Redaktə</a> <form style="display:inline" method="post" onsubmit="return confirm('Silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ga-btn ga-danger">Sil</button></form></td></tr><?php endforeach;?></table></div></div></main></body></html>
